  $sujet${"parties": [{"titre": "المجال الرئيس الأول: درس النصوص", "points": 10, "questions": [{"type": "libre", "numero": "1", "points": 1, "enonce": "انطلق(ي) من ملاحظة **شكل طباعة النص ومصدره** [مسطر في الورقة]، ثم افترض(ي) **نوع الخطاب** [مسطر في الورقة] الذي ينتمي إليه النص.", "correction": "الانطلاق من ملاحظة شكل طباعة النص ومصدره: كُتب النص في شكل أعمدة، ويحيل مصدره على جريدة وعلى تاريخ النشر... (0.25ن ×2) افتراض نوع الخطاب: خطاب صحافي. (0.5ن)"}, {"type": "libre", "numero": "2", "points": 1, "enonce": "حدد(ي) **الفكرتين الأساسيتين** [مسطر في الورقة] اللتين يطرحهما النص.", "correction": "الفكرتان الأساسيتان اللتان يطرحهما النص: - كرم منكوبي زلزال الحوز مع مختلف الزوار جعلهم حديث العالم بأسره؛ (0.5ن) - انبهار العالم بمظاهر التضامن والتلاحم التي عبر عنها المغاربة، خصوصا المنتمين منهم للطبقات البسيطة، تجاه المنكوبين. (0.5ن)"}, {"type": "libre", "numero": "3", "points": 1, "enonce": "اشرح(ي) الفكرة الآتية الواردة في النص: \" كَشفَتْ مِحْنة الكارِثة عن وحدة المغاربة وأصالتهم وتآزرهم، وقُدرتِهم على الصَّبر في أوقات الشِّدَّة والحاجة\".", "correction": "يقبل كل جواب يشرح الفكرة شرحا مستوفيا، من خلال التركيز على توضيح العلاقة بين كارثة الزلزال وتجليات وحدة المغاربة وأصالتهم وتآزرهم، وقدرتهم على الصبر في أوقات الشدة والحاجة. (0.75ن) - سلامة اللغة (0.25ن)"}, {"type": "tableau", "numero": "4", "points": 2, "enonce": "في النص حقلان دلاليان؛ حقل دال على **الدمار والمحن** [مسطر في الورقة]، وحقل دال على **الكرم والتضامن** [مسطر في الورقة]. اجرد(ي) ثلاثة **ألفاظ وعبارات** [مسطر في الورقة] دالة على كل حقل، ثم حدد(ي) **العلاقة القائمة** [مسطر في الورقة] بينهما مع **التعليل** [مسطر في الورقة]، مستعينا(ة) بالجدول الآتي:", "champs": [{"libelle": "الحقل الدال على الدمار والمحن", "reponse": "مشاهد الدمار والموت – محنة الكارثة – أوقات الشدة والحاجة- عيناها تدمعان – قساوة- بلا مأوى - منكوبة... (0.25 × 3 = 0.75 ن)"}, {"libelle": "الحقل الدال على الكرم والتضامن", "reponse": "قيم التضامن والتلاحم والكرم - تآزرهم- التعاضد- مد يد المساعدة – النبل – قوافل المساعدات - ... (0.25 × 3 = 0.75 ن)"}, {"libelle": "العلاقة بينهما", "reponse": "علاقة سبب بنتيجة/ سببية... تقبل باقي الإجابات شريطة أن تكون العلاقة معللة ومقنعة (0.25 ن)"}, {"libelle": "التعليل", "reponse": "الكارثة كشفت كرم المنكوبين وتضامن باقي المغاربة معهم... (0.25 ن)"}]}, {"type": "libre", "numero": "5", "points": 1, "enonce": "أبرز(ي) مُقوِّمَيْن اثنين اعتمدهما الصحافي لإضفاء **الموضوعية والمصداقية** [مسطر في الورقة] على ما نقله من أخبار، **ممثلا** [مسطر في الورقة] لكل منهما بما يناسب من النص.", "correction": "لإضفاء الموضوعية والمصداقية على ما نقله الصحافي من أخبار، اعتمد على: - الإحالة على مصدر الخبر: تناقلت وسائل التواصل الاجتماعي شريطا – كتبت الصحافية موريسون على منصة X ... (0.5ن) - العناية بتوثيق الخبر: من خلال نقل الشهادات والحوارات كما هي: (كيف يمكنني أن أبعث...- حيث كتب أحد المتضامنين: \"لقد نثرنا...) (0.5ن) تقبل باقي المقومات (توظيف لغة تقريرية مباشرة - ....) شريطة أن تكون ملائمة للمطلوب، وأن يتم إبرازها والتمثيل لها من النص."}, {"type": "tableau", "numero": "6", "points": 1, "enonce": "تهيمن على لغة النص الجمل الخبرية، وقد تنوعت بين **السرد والوصف** [مسطر في الورقة]. مثل(ي) لكل منهما بما يناسب **من العمود الثالث** [مسطر في الورقة] من النص، مستعينا(ة) بالجدول الآتي:", "champs": [{"libelle": "مثال يتضمن السرد", "reponse": "لقد نثرنا القمح والإعانات في أعالي الجبال.. ......... (0.5 ن)"}, {"libelle": "مثال يتضمن الوصف", "reponse": "وتلك عجوز جاءت بخطوات متعبة – ينسحب على متن دراجته في هدوء ومن دون بهرجة ......... (0.5 ن)"}]}, {"type": "libre", "numero": "7", "points": 3, "enonce": "اكتب(ي)، بأسلوبك الخاص، فقرة مركزة؛ **تركب(ين)** [مسطر في الورقة] فيها نتائج الفهم والتحليل، **مناقشا(ة)** [مسطر في الورقة] **ومبديا(ة)** [مسطر في الورقة] رأيك الشخصي في **تضامن الفئات الفقيرة مع منكوبي زلزال الحوز** [مسطر في الورقة].", "correction": "- تركيب: نتائج الفهم (0.75 ن) والتحليل (0.75ن) - المناقشة (0.75ن) - إبداء الرأي الشخصي المعلل (0.75ن)"}], "texte": "### صدى عالمي لكَرم المَنكوبين وتضامن المواطنين خلال زلزال الحوز\n\n**متابعون قالوا إن ذلك كشف أصالة المغاربة ووحدتهم وجمال معدنهم**\n\nمراكش: عبد الكبير الميناوي\n\nفي خِضم مَشاهد الدَّمار والموت التي خلَّفها \"زلزالُ الحَوْز\"، بَرزت، بشكل أوضح، قِيم التَّضامُن والتَّلاحُم والكَرَم بين المغاربة؛ إذ كَشفَتْ مِحْنة الكارِثة عن وحْدتهم وأصالتهم وتآزرهم، وجمال مَعْدنهم، وقُدرتِهم على الصَّبر في أوقات الشِّدَّة والحاجة، وتعامُلِهم معها بِكِبْرياء وطِيبَة قَلْب، ومُسارَعتهم إلى التَّضامُن والتعاضد، ومَدِّ يَدِ المُساعَدة إلى بَعْضِهم البعض.\n\nفَمن جانِبٍ أوّل؛ عبَّر المَنْكوبون عن عِزَّة نَفْس وكَرَمٍ مُنقطِعَي النَّظير؛ حيث حَرِصوا على حُسْن وِفَادة مَنْ تَنَقَّل، مِن إعلاميين ومُسْعِفين ومُتضامِنين، إلى مَناطِقهم المُدَمَّرة. وقد تناقلت وسائل التواصل الاجتماعي شَريطا مُصورا لسيِّدة في عَقْدِها السادس خاطَبت وعيناها تدمعان شابّا كان بِصَدد الاستفسار عَن أحْوالها بَعد أحداث الزِّلْزال، قائلة: \"كيف يُمْكنني أن أبْعث إليْك، يا ولدي، ببعْض الزَّعْفَران؟\" نموذج هذه السيدة، التي لم تَتَخَلَّ عن عادة العَطْف على الغَريب وإكْرام الضّيف، حَتّى في أشَدِّ المِحَن قَساوَة، هو مثال لعشرات المشاهد المُؤثِّرة الّتي *[بداية العمود الثاني]* تَناقلتْها القَنواتُ الفضائية ووسائلُ التّواصل الاجتماعي، خلال كارثة الزلزال.\n\nوفي هذا الصدد، كتبت الصّحافيّة سابقا في شبكة \"بي بي سي\"، البريطانية \"أليس هانتر موريسون\" تغريدة، على حسابها بموقع \"إكس X\"، تقول فيها مُعبِّرة عما عاشته من رُعب الزلزال في منطقة الحَوْز: \"ما أَحْبَبْتُه كثيراً في هذه التَّجربة، هو أنَّك لا تستطيع أن تُحْبط المغاربة. إنهم هُنا بلا مأوى، لكنهم ما زالوا يشاركونني ضيافتهم؛ عُروض الشّاي وطاجين الدّجاج... تكادُ لا تنقطع\".\n\nومن جانب آخر، تجلَّت قيم الأصالة والنُّبل عند المغاربة واضحةً خلال مِحنة الزلزال، وجاءت مشاهد التَّضامُن مع المنكوبين، لتُبرز قيم التآخي والتآزر بين أبناء الوطن الواحد، الذين حوّلوا المناطِق المُتضرِّرة إلى وِجهةٍ لمئاتِ قَوافِل المُساعدات القادِمة من مُخْتلف جِهات البَلد.\n\nوتوقَّف كثيرون عند بعض المشاهد التّضامُنية المُعبَّر عنها من لدُن الجميع، خُصوصا المُنتمِين مِنهم لطبقات اجتماعية بسيطة؛ إذ خلَّفت مُبادراتُهم صدى واسعا في العالَم بأسْرِه، شَدُّوا بها أنظار العالم الذي انْبَهر بِروحِهم التَّضامُنيَّة التي كشفت *[بداية العمود الثالث]* كَرمَ الشعب وعظمته، وغِنى نفوس الفقراء. فهذه سيِّدة تُناشِد أحد المُكلَّفين بنقْل المُساعدات للمتضررين، أن يَقْبل مِنها خاتَم الذهب، الذي أهداه لها زوجها منذ ان التقاها، بل هو كلّ ما تملك، ليبيعه ويُعين بثَمنه ما يَقْضي به حاجَةً، وتِلك عَجُوز جاءت، بخُطوات مُتعَبة، تَحمل قِنِّينة زَيْتٍ لِتُسَلِّمها لِلجانِ جَمع المساعدات، وذلك شَيْخٌ جاء يَحْمل كيس دَقِيقٍ قَبل أن ينسحب على مَتن درَّاجته الهَوائِيّة في هُدوء ومن دون بَهْرجة... وغيرها من الأمثلة الإنسانية التي ستبقى في خزانة التاريخ.\n\nوالمُثير في مشاهد الهَبَّة التَّضامنية الَّتي شَغلت المغاربة عمَّا سواها، خِلال مِحْنة الزلزال، وما رافَقها من شهادات وكتابات مُوثِّقة للحدث، أنَّ موجات التضامن شَملَت أيضا حيوانات المناطق المنكوبة. وقد وثق ذلك أحد المُتضامنين الَّذين تنقَّلوا إلى مناطق الزلزال، حيث كتب: \"لقد نثرنا القمح والإعانات في أعالي الجبال، حتى لا يُقال إن الطَّير والوحوش ماتَت جوعا في بلد المغرب\"، مقتبسا قول \"عمر بن عبد العزيز\"، واعتبرها صدقة ورحمة على ضحايا الزلزال.\n\n*جريدة الشرق الأوسط، نُشر بتاريخ 17 سبتمبر 2023م في الساعة 12:30. (بتصرف)*", "consigne": "اقرأ(ئي) النص، ثم أجب/ أجيبي عن الأسئلة الآتية في ورقة الامتحان."}, {"titre": "المجال الرئيس الثاني: مكون علوم اللغة", "points": 4, "questions": [{"type": "tableau", "numero": "1 أ", "points": 1, "enonce": "استخرج(ي) من **العمود الأول** [مسطر في الورقة] للنص جملتين؛ تتضمن الأولى **تمييز الملحوظ** [مسطر في الورقة]، والثانية **استفهاما** [مسطر في الورقة]، ثم استخلص(ي) عناصر كل منهما وفق الجدولين أسفله (الجدول الأول):", "champs": [{"libelle": "الجملة المتضمنة للتمييز", "reponse": "حتى في أشد المحن قساوة (0.5ن)"}, {"libelle": "تمييز الملحوظ", "reponse": "قساوةً (0.25ن)"}, {"libelle": "حكمه الإعرابي", "reponse": "النصب وجوبا (0.25ن)"}]}, {"type": "tableau", "numero": "1 ب", "points": 1, "enonce": "(الجدول الثاني):", "champs": [{"libelle": "جملة الاستفهام", "reponse": "كيف يمكنني أن أبعث إليك ببعض الزعفران؟ (0.25ن)"}, {"libelle": "أداة الاستفهام", "reponse": "كيف (0.25ن)"}, {"libelle": "فائدة الأداة", "reponse": "التصور (الحال والهيأة) (0.5ن)"}]}, {"type": "libre", "numero": "2 أ", "points": 1, "enonce": "ايت(ي)، من إنشائك الخاص، بما يأتي: جملة تستعمل فيها العدد \"16\" **مكتوبا بالحروف** [مسطر في الورقة] مع **معدود مؤنث** [مسطر في الورقة]. **(مع الضبط بالشكل التام)** [مسطر في الورقة]", "correction": "تقبل كل جملة مفيدة تتضمن العدد 16 مكتوبا بالحروف مع معدود مؤنث (ستَّ عشْرَة....)؛ (تركيب الجملة 0.75ن - شكل العدد والمعدود 0.25ن)"}, {"type": "libre", "numero": "2 ب", "points": 1, "enonce": "ايت(ي)، من إنشائك الخاص، بما يأتي: جملة تتضمن **أسلوب النهي** [مسطر في الورقة] الذي يفيد **الدعاء** [مسطر في الورقة].", "correction": "يقبل كل مثال يتضمن أسلوب النهي (0.25ن) الذي يفيد الدعاء (0.75ن)."}]}, {"titre": "المجال الرئيس الثالث: مكون التعبير والإنشاء", "points": 6, "texte": "أظهرت تجربة \"زلزال الحَوْز\" أهمية وسائل التواصل الاجتماعي في حياتنا اليومية؛ حيث ساهمت في بث نداءات الاستغاثة بشكل سريع، وفي نشر الوعي بالكارثة، وفي تنسيق عمليات جمع التبرعات.\n\nاكتب(ي)، في حدود خمسة عشر (15) سطرا، موضوعا إنشائيا؛ توسع(ين) فيه هذه الفكرة، مسترشدا(ة) بما اكتسبته من تقنيات في مهارة \"توسيع فكرة\".", "questions": [], "redaction": true}]}$sujet$::jsonb
)
